CARDS = [
 {"f":"Industry versus business sector versus economic sector","b":"Industry: firms meeting the same need. Business sector: related industries. Economic sector: agriculture, manufacturing, utilities, services."},
 {"f":"First step in industry analysis","b":"<b>Defining the industry</b> the company operates in."},
 {"f":"NIC, GICS, NAICS","b":"NIC: India's National Industry Classification. GICS: Global Industry Classification Standard. NAICS: North American Industry Classification System."},
 {"f":"GICS structure (MSCI, March 2023)","b":"4 tiers: <b>11</b> sectors, <b>25</b> industry groups, <b>74</b> industries, <b>163</b> sub-industries."},
 {"f":"How should an analyst classify a company like PVR?","b":"Group it with businesses that share the <b>same driving factors</b>."},
 {"f":"Defensive industries","b":"Low <b>income elasticity</b>; little affected by economic cycles. Food, agricultural inputs, healthcare."},
 {"f":"Semi-cyclical industries","b":"Grow in expansion, fall in recession, but keep base demand. Consumer durables."},
 {"f":"Deep cyclical industries","b":"Extreme swings from economic and commodity cycles. Capital goods, steel."},
 {"f":"Top-down versus bottom-up market sizing","b":"Top-down: start from macro factors (patients &times; spend). Bottom-up: add up individual companies' data."},
 {"f":"Tyre sample: organised players Rs 24,000 crore, unorganised 20%. Market size?","b":"24,000 &divide; 0.8 = <b>Rs 30,000 crore</b>."},
 {"f":"Five drivers of secular trends","b":"Technology, change in income, demography, culture and tastes, regulation or policy."},
 {"f":"Secular trend from GST (book)","b":"More efficient logistics, so <b>lower demand for new commercial vehicles</b>."},
 {"f":"Value migration","b":"A shift that gives one party a long-term advantage at another's cost, moving shareholder value."},
 {"f":"Four kinds of value migration","b":"Across geographies, across industries, across the value chain, across companies in one industry (least common)."},
 {"f":"Value chain migration example (book)","b":"Cheap Indian telecom hurt telecom companies but helped <b>digital content</b> providers."},
 {"f":"Five stages of the business life cycle","b":"Pioneering, growth, mature, declining, reinvention and revival (rare)."},
 {"f":"Indian life cycle example (book)","b":"<b>Call taxis</b>: grew with phones and incomes, declined with app-based aggregators."},
 {"f":"Porter's five forces: horizontal and vertical (book)","b":"Horizontal: substitutes, new entrants, established rivals. Vertical: supplier power, buyer power."},
 {"f":"When was Porter's model developed?","b":"<b>1979</b>, by Dr. Michael Porter."},
 {"f":"Unattractive industries per Porter (book)","b":"Aviation, telecom, retail, textile, sugar, power."},
 {"f":"Attractive industries per Porter (book)","b":"Education, FMCG, healthcare, IT."},
 {"f":"High rivalry leads to...","b":"<b>Lower</b> pricing power and <b>lower</b> incomes."},
 {"f":"Four signs of high rivalry","b":"Many companies; little differentiation; same strategies (low price, long credit); low switching cost."},
 {"f":"Munger on price competition","b":"\"If only basis of competition in an industry is pricing, it is a self-defeating business.\""},
 {"f":"Industries with no threat of substitutes (book)","b":"Power, healthcare, education."},
 {"f":"Kodak's lesson","b":"Its engineers invented the digital camera, but it protected film, missed the substitute threat and went bankrupt."},
 {"f":"When is buyer power high?","b":"Strong competition among sellers; standardised products; close substitutes with low switching cost."},
 {"f":"When is supplier power high?","b":"Few suppliers and many buyers; critical inputs; differentiated products; no substitutes; high switching cost."},
 {"f":"Examples of strong supplier power (book)","b":"Sugarcane farmers (price set by government); OPEC in crude oil; hospitals and schools."},
 {"f":"Entry barriers","b":"Licensing, patents, huge specialised investment, strong brands, distribution, customer loyalty. Buffett's \"moat\"."},
 {"f":"Five features of an attractive industry","b":"Low competition, high barriers to entry, weak supplier power, weak buyer power, few substitutes."},
 {"f":"PESTLE","b":"Political, Economic, Socio-cultural, Technological, Legal, Environmental. External factors, mainly for choosing a country."},
 {"f":"STEEPLED","b":"PESTLE plus <b>Ethics</b> and <b>Demographics</b>."},
 {"f":"Legal factor examples of investor discomfort (book)","b":"Vodafone retrospective tax; cancelled telecom and mining licences."},
 {"f":"What does the BCG matrix analyse?","b":"Segments <b>within a business</b>, as a portfolio, through market growth and cash generation."},
 {"f":"BCG: Star","b":"Fast-growing market, large share. Book: <b>Cera Sanitaryware</b>."},
 {"f":"BCG: Cash cow","b":"Low growth, established share, steady cash. Book: <b>Navneet Publications</b>, <b>Colgate</b>."},
 {"f":"BCG: Question mark","b":"Fast-growing market, low share. Book: <b>Tata Nano</b> (failed), <b>Bajaj Pulsar</b> (succeeded)."},
 {"f":"BCG: Dog","b":"Slow growth, intense competition, low cash."},
 {"f":"SCP","b":"Structure (players, concentration), Conduct (pricing, seasonality, cyclicality), Performance (RoE, RoIC, WACC). An extension of Porter."},
 {"f":"Unit of pricing","b":"What a company treats as one unit when pricing. Starbucks prices per <b>patron</b>, not per cup."},
 {"f":"Three types of constraint","b":"Demand side, supply side, regulatory."},
 {"f":"Constraint to KPI","b":"Limited market: <b>penetration rate</b>. Limited capacity: <b>capacity utilisation</b>. Regulatory: regulators' metrics."},
 {"f":"Airline KPIs","b":"Passenger or cargo km; price per passenger or cargo km; capacity and occupancy rate."},
 {"f":"Bank and NBFC KPIs","b":"Net interest margin, capital adequacy, NPA ratio, deposit and loan growth, CRR and SLR, CASA ratio."},
 {"f":"IT services KPIs","b":"FTEs billed, revenue per FTE, bench strength, attrition, constant currency growth, customer concentration, million dollar clients."},
 {"f":"Media KPIs","b":"Readership, viewership, TRPs, site visitors; ad realisation per unit; content acquisition cost."},
 {"f":"Retail KPIs","b":"Number of stores; <b>same-store sales growth</b>."},
 {"f":"Telecom KPIs","b":"<b>ARPU</b>, churn rate, subscriber acquisition cost, market share."},
 {"f":"Kerala fat tax","b":"2017: <b>14.5%</b> additional tax on junk food."},
 {"f":"Direct versus indirect tax","b":"Direct: the person bearing it pays it (income tax). Indirect: seller collects, consumer bears (GST)."},
 {"f":"R&amp;D tax incentive (book)","b":"Claim <b>1.5 times</b> actual spend on certain scientific research."},
 {"f":"Deferred tax asset versus liability","b":"Asset: paying more tax now, less later. Liability: paying less now, more later."},
 {"f":"Corporate income tax rate (book)","b":"<b>30%</b>; <b>25%</b> if turnover below Rs 400 crore. Optional schemes 15% to 25%."},
 {"f":"MAT","b":"If tax is below <b>15% of book profits</b>, pay 15% + cess + surcharge. Excess is MAT credit."},
 {"f":"Surcharge rates, AY 2025-26 (book)","b":"<b>12%</b> above Rs 10 crore income; <b>7%</b> for Rs 1 to 10 crore; nil below Rs 1 crore. All to the central government."},
 {"f":"Cess (book)","b":"<b>4%</b> on tax plus surcharge, for health and education. Used only for its purpose."},
 {"f":"Which goods still have excise and VAT?","b":"Liquor, petrol, diesel."},
 {"f":"STT","b":"Securities Transaction Tax, paid on sale of securities. Discourages short-term trading; affects traders and brokers."},
 {"f":"Four sources for industry analysis","b":"Industry reports; annual reports (MD&amp;A); associations and trade bodies; relevant ministry."},
]

